    translateDocument(docName, lang = 'hi') {
    if (!docName || lang === 'en') return docName;
    const lower = docName.toLowerCase();
    for (const key in DOCUMENT_MAP) {
      if (lower.includes(key)) {
        return DOCUMENT_MAP[key][lang] || docName;
      }
    }
    return docName;
  }

